insert into youtube_uploads (source_type, source_ref, context, title, description, tags, category_id, privacy_status, made_for_kids, status)
select r.source_type, r.source_ref, r.context, r.title, r.description, array(select jsonb_array_elements_text(r.tags)), r.category_id, r.privacy_status, r.made_for_kids, r.status
from jsonb_to_recordset($j$[{"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%201%20-%20Quantum%20Revenue%20Efficiency%20Model%20Intro.mp4", "context": {"academy_chapter_video_id": "da09c87e-3c9a-4a11-95bd-a2c836927662", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130208, "queued_by": "claude-daily-academy-upload"}, "title": "The Quantum Revenue Efficiency Model: Keep, Grow, Multiply, Convert, Expand", "description": "The fastest revenue is usually the revenue closest to you. Shawn Peterson introduces the Quantum Revenue Efficiency Model, five places to find revenue in order: keep the customers you have, grow within them, multiply through referrals and partners, convert what is already in your funnel, then expand to new cold prospects.\n\nThis is part 1 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}, {"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%202%20Keep%20-%20Finding%20Opportunities%20to%20Strengthen%20Customer%20Loyalty.mp4", "context": {"academy_chapter_video_id": "1b77ea62-79e1-4779-ba6b-fb0ea9c3b3ea", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130209, "queued_by": "claude-daily-academy-upload"}, "title": "Keep: Strengthen Customer Loyalty Before You Chase New Revenue", "description": "The best way to grow is to keep the customers you already have. Keep, the first step in the model, covers where to look first, from speeding up accounts receivable to spotting the loyalty risks that quietly cost you revenue.\n\nThis is part 2 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}, {"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%203%20-%20Grow%20-%20Crosseling%20to%20your%20current%20clients.mp4", "context": {"academy_chapter_video_id": "3b975c29-7df4-4c79-bcd0-4079cbe8afd9", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130210, "queued_by": "claude-daily-academy-upload"}, "title": "Grow: How to Cross-Sell to Your Current Clients", "description": "Map the total addressable market inside your own customer base, then find which clients buy one thing from you but could buy more. Shawn walks through building the cross-sell list step by step, using an office technology example.\n\nThis is part 3 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}, {"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%204%20-%20Grow%20(p2)%20-%20Identify%20upsell%20opportunites%20among%20current%20clients.mp4", "context": {"academy_chapter_video_id": "704a1906-5271-4a3e-8892-6ea5b9725605", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130211, "queued_by": "claude-daily-academy-upload"}, "title": "Grow: Find Upsell Opportunities in Your Customer Base", "description": "Your next list is clients who could buy more of what they already buy from you. How to find them, size the opportunity, and prioritize who to call first.\n\nThis is part 4 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}, {"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%205%20-%20Grow%20(p3)%20-%20Building%20a%20Resell%20List.mp4", "context": {"academy_chapter_video_id": "ba8ebbe2-008c-49b4-9fdf-c17997947a84", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130212, "queued_by": "claude-daily-academy-upload"}, "title": "Grow: Build a Resell List From Current and Past Clients", "description": "Which clients bought something last year or last cycle that is due again? How to build a resell list so renewals and repeat purchases stop depending on memory.\n\nThis is part 5 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}, {"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%206%20-%20Multiply%20-%20Strategies%20for%20Multiplying%20Client%20Relationships.mp4", "context": {"academy_chapter_video_id": "d774fbd2-fbc8-4f3b-ae53-068928c679c2", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130213, "queued_by": "claude-daily-academy-upload"}, "title": "Multiply: Turn Client Relationships Into Referrals and Partnerships", "description": "Multiply combines referrals, introductions and partners into one motion. How to track every referral source and turn happy clients and partners into a repeatable pipeline.\n\nThis is part 6 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}, {"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%207%20-%20Convert%20-%20Optimizing%20Conversion%20Strategies.mp4", "context": {"academy_chapter_video_id": "da8d27be-a790-4817-bb46-2c84682f4f38", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130214, "queued_by": "claude-daily-academy-upload"}, "title": "Convert: Stop Losing Revenue Inside Your Funnel", "description": "A lot of dollars fall off the wagon between first contact and closed deal. This section of the model covers the audiences already in your funnel: former clients, stalled deals, lost deals, past meetings, MQLs and SQLs.\n\nThis is part 7 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}, {"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%208%20-%20Convert%20(p2)%20-%20Reengaging%20Former%20Clients.mp4", "context": {"academy_chapter_video_id": "72b30bc2-4dcb-4f3f-bd8b-7ac3fd514097", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130215, "queued_by": "claude-daily-academy-upload"}, "title": "Convert: How to Win Back Former Clients", "description": "Clients leave for all kinds of reasons, and many find the grass was not greener. How to build a former client list, time the outreach, and open the conversation again.\n\nThis is part 8 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}, {"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%209%20-%20Convert%20(p3)%20-%20Reactivating%20Stalled%20Deals.mp4", "context": {"academy_chapter_video_id": "7f6abcb2-5106-4339-8a4b-9f5e49c2536c", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130216, "queued_by": "claude-daily-academy-upload"}, "title": "Convert: How to Reactivate Stalled Deals", "description": "Deals that stop moving usually die from too little follow-up, not a real no. How to find stalled and delayed deals in your pipeline and get them moving again.\n\nThis is part 9 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}, {"source_type": "url", "source_ref": "https://20682069.fs1.hubspotusercontent-na1.net/hubfs/20682069/QUANTUM/VIDEOS/Quantum%20Academy/Revenue%20Efficiency%20Model/Chapter%2010%20-%20Convert%20(p4)%20-%20Reengaging%20Lost%20Deals.mp4", "context": {"academy_chapter_video_id": "bc1de8c2-b4fb-4932-8d3f-740d147add0a", "lsvt_course_id": 226502, "lsvt_chapter_id": 1130217, "queued_by": "claude-daily-academy-upload"}, "title": "Convert: Re-engage Lost Deals Before Their Contract Renews", "description": "Lost a deal to a two or three year contract? The window opens again before it ends. How to track lost deals and reach back out about six months before renewal.\n\nThis is part 10 of 15 in the Quantum Revenue Efficiency Model series from Quantum Academy.\n\nSee the model: https://www.thequantumleap.business/?utm_source=youtube&utm_medium=video&utm_campaign=rev-efficiency-model#revenue-efficiency-model\nBook time with Shawn: https://meetings.hubspot.com/shawn-peterson\n\nShawn Peterson is CEO of Quantum Business Solutions, a HubSpot Platinum Solutions Partner that helps B2B sales teams systemize, optimize and automate revenue growth. https://www.thequantumleap.business", "tags": ["Revenue Efficiency Model", "B2B sales", "revenue growth", "sales strategy", "Quantum Academy", "Shawn Peterson", "Quantum Business Solutions"], "category_id": "27", "privacy_status": "public", "made_for_kids": false, "status": "pending"}]$j$::jsonb) as r(source_type text, source_ref text, context jsonb, title text, description text, tags jsonb, category_id text, privacy_status text, made_for_kids boolean, status text)
where not exists (select 1 from youtube_uploads u where u.source_ref = r.source_ref and u.status in ('pending','uploading','completed'))
returning id, left(title,60) title, status;